'use client';

// The app shell. Layout A (`screen`): one screen at a time. Compact: bottom tabs (at most four; more give three plus « Plus »), or with `compactNav="sheet"` no bar and the sidebar as a sheet from the header. Expanded:
// the shadcn sidebar (icon rail plus NavUser). Layout B (`workspace`): the same, with a screen made of a `ListDetail`; the sidebar starts
// as the icon rail below 1280px, and from 1280px when the screen has no `sidebar` content (D-1909); the person's choice is kept. Layout C (`chat`): the one nav item renders the app's `AgentWorkspace`,
// untouched, below the same sidebar, account menu and header; there is no shell agent (the page is the chat). The shell imports nothing from pi-app: a layout C app installs the `pi-app` item itself. One header per screen
// (`useScreenHeader`). The AgentLayer is mounted once, here.
// Host concern: Pi has no layout; the screen on show travels as the agent's context (useAgentContext -> createPromptContext).
import { useEffect, useState, useSyncExternalStore } from 'react';
import { afterStacksBack } from '../utils/back';
import type { ReactNode } from 'react';
import { Button } from '@/components/ui/button';
import { AccountAvatar, AccountChoices } from './account';
import type { AccountSpec } from './account';
import { AgentDockLayout, AgentLayer, AgentLayerProvider } from './agent-layer';
import type { AgentComposer } from './agent-layer';
import type { AgentSpec } from './agent-layer';
import { NoPanelLayout } from './shell-panel';
import type { ShellPanel } from './shell-panel';
import { ScreenActiveContext, useAgentContext } from './agent-context';
import { useIsCompact } from './compact';
import { HeaderProvider, ScreenHeader } from './header';
import { AppSidebar, ScreenSidebarSheet, TabBar } from './nav';
import { ResizableSidebarProvider } from './sidebar-resize';
import { useSidebarOpen } from './sidebar-open';
import type { NavItem } from './nav';
import { AppSheet } from './app-sheet';
import { appShellText } from './text';
import { ScreenHeaderSlotContext } from '../utils/screen-header-slot';
import type { AppShellLocale, AppShellText } from './text';

export interface AppShellProps {
  /** A `screen` (tabs), B `workspace` (list and detail), C `chat` (the app's `AgentWorkspace`; no `agent`). */
  readonly layout: 'screen' | 'workspace' | 'chat';
  readonly title: string;
  readonly nav: readonly NavItem[];
  /** Wide-screen navigation: `hover` reveals labels over the page on hover or keyboard focus. Default: `icon` (the native sidebar toggle). */
  readonly rail?: 'icon' | 'hover';
  /** Phone navigation: `tabs` (default) is the bottom tab bar; `sheet` has no bar, the header's leading button opens the sidebar (the nav items, a screen's `sidebar` content and the account) as a sheet. */
  readonly compactNav?: 'tabs' | 'sheet';
  readonly agent?: AgentSpec;
  /** Where the assistant's field sits on a wide screen: `dock` (default) in the dock under the thread; `content` pinned under the page content, at the content's width, with the dock holding only the thread (a send, or `talkAbout`, opens it). A phone keeps the peek drawer either way. */
  readonly composer?: AgentComposer;
  /** Consume agent/open/input launch parameters on mount (default). `false` leaves the URL and layer untouched. */
  readonly agentLink?: false;
  /** A panel beside the app, opened from the account menu. The product manager is `pmPanel` from the Factory's `platform-ui/pm-panel`. */
  readonly panel?: ShellPanel;
  readonly account?: AccountSpec;
  /** The language of the shell's own words and the layer's (« Se déconnecter », « Plus », « Ouvrir l’assistant »…). When set it wins over the agent's `chatProps.locale` and the panel's; without it `chatProps.locale`, then the panel's, then English. */
  readonly locale?: AppShellLocale;
  /** The app's router owns the URL; the shell only reports the choice. */
  readonly route: { readonly id: string; readonly onChange: (id: string) => void };
  /**
   * `true`: a backdrop blur behind dialogs, alert dialogs, sheets and drawers (default `false`: only their dim; blurring the page costs
   * frames on slow phones). Overlays live in a portal, so the shell marks `<html data-overlay-blur="on">` while it is mounted; the
   * shadcn overlays carry the rule (`in-data-[overlay-blur=on]:backdrop-blur-[var(--overlay-blur,4px)]`: an item's CSS stays inside `.app-shell`).
   */
  readonly overlayBlur?: boolean;
  /**
   * The wide-screen left pane can be resized (default `false`): its rail becomes a drag handle (`role="separator"`, arrow keys, double-click to reset),
   * between `min` and `max` rem (14 and 28). Fine pointer only; the phone sheet keeps `--sidebar-width-mobile`. The width is remembered per app and
   * per person; the theme's `--sidebar-width` stays the default. `true` or `{ min, max }`.
   */
  readonly resizable?: boolean | { readonly min?: number; readonly max?: number };
  /**
   * A stable id of the app (its slug), which names the app in the stored sidebar width instead of `title`: two apps with the same title on one origin,
   * or an app whose title is renamed or translated, keep (or do not share) their widths. Pass it with `resizable`; without it (or with an empty one) the key uses `title`.
   */
  readonly appId?: string;
}

/** The shells that ask for the blur now, and what `<html data-overlay-blur>` held before the first of them (the app's own HTML may set it). */
const blurOwners = new Set<symbol>();
let blurBefore: string | undefined;

/** `<html data-overlay-blur="on">` while any shell asks for it: set by the first owner, restored when the last one leaves. */
function useOverlayBlur(blur: boolean) {
  useEffect(() => {
    if (!blur || typeof document === 'undefined') return;
    const root = document.documentElement;
    const owner = Symbol('overlay-blur');
    if (blurOwners.size === 0) blurBefore = root.dataset.overlayBlur;
    blurOwners.add(owner);
    root.dataset.overlayBlur = 'on';
    return () => {
      blurOwners.delete(owner);
      if (blurOwners.size > 0) return;
      if (blurBefore === undefined) delete root.dataset.overlayBlur;
      else root.dataset.overlayBlur = blurBefore;
    };
  }, [blur]);
}

/** Registers what is on show for the agent. A screen's own `useAgentContext` is mounted later and wins. */
function ShellContext({ name }: { readonly name: string }): null {
  useAgentContext({ name, params: {} });
  return null;
}

function ScreenContent({ item }: { readonly item: NavItem }): ReactNode { return item.render(); }

/** Every screen stays mounted; the ones not on show are `hidden` and do not register a header or a context. */
function Screens({ items, activeId, scrolls, slot }: { readonly items: readonly NavItem[]; readonly activeId: string; readonly scrolls: boolean; readonly slot: HTMLElement | null }) {
  return <div className="relative min-h-0 flex-1">
    {items.map(item => <ScreenActiveContext.Provider key={item.id} value={item.id === activeId}><ScreenHeaderSlotContext.Provider value={item.id === activeId ? slot : null}>
      <div hidden={item.id !== activeId} data-testid={`screen-${item.id}`} className={scrolls ? 'h-full overflow-y-auto overscroll-contain' : 'h-full overflow-hidden'}><ScreenContent item={item} /></div>
    </ScreenHeaderSlotContext.Provider></ScreenActiveContext.Provider>)}
  </div>;
}

function Shell({ resizable, appId, compactNav, layout, rail, title, nav, agent, panel, account, route, text }: { readonly resizable: AppShellProps['resizable']; readonly appId: string | undefined; readonly compactNav: NonNullable<AppShellProps['compactNav']>; readonly rail: NonNullable<AppShellProps['rail']>; readonly layout: AppShellProps['layout']; readonly title: string; readonly nav: readonly NavItem[]; readonly agent: AgentSpec | undefined; readonly panel: ShellPanel | undefined; readonly account: AccountSpec | undefined; readonly route: AppShellProps['route']; readonly text: AppShellText }) {
  const improve = panel && panel.menu !== false ? panel.label ?? text.improve : undefined;
  const Layout = panel?.Layout ?? NoPanelLayout;
  const compact = useIsCompact();
  const sheet = compact && compactNav === 'sheet';
  const [accountOpen, setAccountOpen] = useState(false);
  // The header's slot for the screen on show (an embedded AgentWorkspace puts its bar's controls there).
  const [slot, setSlot] = useState<HTMLElement | null>(null);
  const active = nav.find(item => item.id === route.id) ?? nav[0];
  // The left pane: the person's kept choice, else the first visit's default (D-1909). `rail="hover"` keeps its own reveal and today's default.
  const today = rail !== 'hover' && layout === 'screen';
  const paneOpen = useSidebarOpen(rail !== 'hover', { app: appId || title, person: account?.email }, layout === 'screen', today, Boolean(active?.sidebar));
  if (!active) return null;
  // A nav choice waits for an open detail's stack entry to go back, so the app's router can replace the URL without that Back restoring
  // the detail's. Choosing the screen already on show changes nothing and keeps the detail.
  const choose = (id: string) => { if (id === active.id) route.onChange(id); else afterStacksBack(() => route.onChange(id)); };
  const hasAccount = Boolean(account) || improve;
  const avatar = hasAccount ? <>
    <Button variant="ghost" size="icon" data-testid="account-button" aria-label={account?.name ?? text.account} title={account?.name ?? text.account} onClick={() => setAccountOpen(true)}><AccountAvatar account={account} /></Button>
    <AppSheet open={accountOpen} onOpenChange={setAccountOpen} title={text.account}>
      <AccountChoices account={account} improve={improve} text={text} done={() => setAccountOpen(false)} />
    </AppSheet>
  </> : null;
  // The structure is the same compact or expanded, so a resize never remounts a screen.
  return <ResizableSidebarProvider data-testid="app-shell" resizable={resizable} app={appId || title} person={account?.email} defaultOpen={today} {...paneOpen} className="app-shell h-dvh min-h-0 overflow-hidden">
    {(!compact || sheet) && <AppSidebar rail={sheet ? 'icon' : rail} identity={{ app: appId || title, person: account?.email }} title={title} items={nav} activeId={active.id} onChange={choose} agent={agent} account={account} improve={improve} text={text} />}
    <AgentDockLayout>
      <div data-slot="sidebar-inset" className="relative flex min-h-0 min-w-0 w-full flex-1 flex-col overflow-hidden bg-card">
      <Layout screen={active.label} navigation={compact && !sheet ? <TabBar items={nav} activeId={active.id} onChange={choose} text={text} /> : undefined}>
        <ShellContext name={active.label} />
        <ScreenHeader fallbackTitle={active.label} compact={compact} avatar={avatar} menu={sheet} screenSidebar={compact && !sheet && active.sidebar ? <ScreenSidebarSheet key={active.id} item={active} text={text} /> : undefined} text={text} slotRef={setSlot} />
        <Screens items={nav} activeId={active.id} scrolls={layout === 'screen'} slot={slot} />
      </Layout>
      </div>
    </AgentDockLayout>
    <AgentLayer />
  </ResizableSidebarProvider>;
}

const never = () => () => {};

export function AppShell(props: AppShellProps) {
  const { layout, rail = 'icon', compactNav = 'tabs', agent, panel, title, nav, account, route } = props;
  if (layout === 'chat' && agent) throw new Error('AppShell layout "chat" takes no `agent`: the page is the chat (use `panel` for the product manager)');
  const text = appShellText(props.locale ?? agent?.chatProps?.locale ?? (panel?.locale as AppShellLocale | undefined));
  useOverlayBlur(props.overlayBlur ?? false);
  const alone = useSyncExternalStore(never, () => panel?.page?.matches() ?? false, () => false);
  if (alone && panel?.page) return <panel.page.Page config={panel.config} appName={title} locale={props.locale} />;
  return <AgentLayerProvider agent={agent} composer={props.composer} panel={panel} locale={props.locale} agentLink={props.agentLink} appName={props.title} modeIdentity={{ app: props.appId || title, person: account?.email, screen: layout === 'screen' }}>
    <HeaderProvider><Shell resizable={props.resizable} appId={props.appId} compactNav={compactNav} layout={layout} rail={rail} title={title} nav={nav} agent={agent} account={account} route={route} panel={panel} text={text} /></HeaderProvider>
  </AgentLayerProvider>;
}

'use client';

// The one list/detail primitive of layout B. Expanded: the list (20rem, or a `railWidth` rail when `collapsible` and folded; its own scroll) and the detail side by side. Compact: one pane at a
// time; opening a detail is a stack step (one history entry, Back returns to the list) and the list stays mounted, hidden, so its scroll is
// kept. Host concern: Pi has no layout. A deep link that mounts with a detail needs nothing more: the Back manager's entry sits above the
// one the page was opened on, and the app's `onBack` (called by Back, and by « ← » which is Back) clears the selection and replaces the URL.
import { useContext, useState } from 'react';
import type { ReactNode } from 'react';
import { ChevronsLeftIcon, ChevronsRightIcon } from '../_shared/icons';
import { Button } from '@/components/ui/button';
import { cn } from '../utils/utils';
import { ScreenActiveContext } from './agent-context';
import { useBackLayer } from '../utils/back';
import { useIsCompact } from './compact';
import { useScreenHeader } from './header';

export interface ListDetailProps {
  /** The list pane (the app's own list; a card list when compact is the app's choice through `useIsCompact`). */
  readonly list: ReactNode | ((state: { readonly collapsed: boolean }) => ReactNode);
  /** `null` = nothing selected. */
  readonly detail: ReactNode | null;
  /** Clears the selection and replaces the URL: called by compact Back and by the header's « ← » (which goes through the browser's Back). */
  readonly onBack: () => void;
  /** Wide screens: what the detail pane shows while nothing is selected (centred, e.g. a muted line « Choisissez une consultation »). Default: nothing. */
  readonly empty?: ReactNode;
  /** The detail's header title when compact (default: the screen's own). */
  readonly title?: string;
  /** Wide screens only: the list pane can fold to a narrow rail (`railWidth`), with a toggle on its edge. Give `list` as a function to render the rail's content. Default: fixed 20rem, no toggle. */
  readonly collapsible?: boolean;
  /** Controlled fold state; without it the pane keeps its own (starting open). */
  readonly collapsed?: boolean;
  readonly onCollapsedChange?: (collapsed: boolean) => void;
  /** The rail's width when collapsed (any CSS length). Default `3rem`, the shell's icon rail. */
  readonly railWidth?: string;
  /** The toggle's accessible names. Default English. */
  readonly labels?: { readonly collapse: string; readonly expand: string };
}

/** Which panes show: both when expanded; when compact the detail if one is selected, else the list. */
export function listDetailView(compact: boolean, detail: ReactNode | null): 'list' | 'detail' | 'both' {
  return !compact ? 'both' : detail === null ? 'list' : 'detail';
}

export function ListDetail({ list, detail, empty, onBack, title, collapsible, collapsed: controlled, onCollapsedChange, railWidth = '3rem', labels = { collapse: 'Collapse the list', expand: 'Expand the list' } }: ListDetailProps) {
  const compact = useIsCompact();
  const [own, setOwn] = useState(false);
  const folds = Boolean(collapsible) && !compact;
  const collapsed = folds && (controlled ?? own);
  const toggle = () => { if (controlled === undefined) setOwn(!collapsed); onCollapsedChange?.(!collapsed); };
  const active = useContext(ScreenActiveContext);
  const view = listDetailView(compact, detail);
  const stacked = view === 'detail';
  useBackLayer(active && stacked, onBack, 'stack');
  // « ← » is the browser's Back, so there is one path: the popstate calls `onBack`, and the URL the entry below holds is the one the app then replaces.
  useScreenHeader(stacked ? { back: () => history.back(), ...(title ? { title } : {}) } : {}, { overlay: true });
  return <div data-testid="list-detail" data-view={view} className="flex h-full min-h-0">
    <div hidden={view === 'detail'} data-testid="list-pane" data-collapsed={folds ? collapsed : undefined} style={collapsed ? { width: railWidth } : undefined}
      className={cn('min-h-0 overflow-y-auto overscroll-contain', compact ? 'w-full' : collapsed ? 'shrink-0' : 'w-80 shrink-0')}>{folds && <div className={cn('flex p-1', collapsed ? 'justify-center' : 'justify-end')}>
        <Button variant="ghost" size="icon-sm" data-testid="list-toggle" aria-expanded={!collapsed} aria-label={collapsed ? labels.expand : labels.collapse} title={collapsed ? labels.expand : labels.collapse} onClick={toggle}>
          {collapsed ? <ChevronsRightIcon /> : <ChevronsLeftIcon />}
        </Button>
      </div>}
      {typeof list === 'function' ? list({ collapsed }) : list}</div>
    <div hidden={view === 'list'} data-testid="detail-pane" className={cn('min-h-0 min-w-0 flex-1 overflow-y-auto overscroll-contain', view !== 'list' && detail === null && empty != null && 'grid place-items-center p-6 text-sm text-muted-foreground')}>{detail ?? empty}</div>
  </div>;
}

// The screen's one left margin. A screen wraps its content in `ScreenBody`: it pads the inline sides with `--screen-gutter` (the theme token; 1rem, 0.75rem under
// `data-density="compact"`, fallback 1rem), the same value the shell's header title starts on, so title and body share one left edge. Block padding is the gutter too.
// A list, table or `ListDetail` that draws its own rows passes `bleed`: no inline padding (rows and dividers run edge to edge), and the first cell of each
// `li`, `tr` or `[role=row]` gets `padding-inline-start: var(--screen-gutter, 1rem)` from the app-shell item's css (zero specificity: a row's own padding wins), so its text still sits on the gutter.
// Host concern: Pi has no layout.
import type { ComponentProps } from 'react';

export interface ScreenBodyProps extends ComponentProps<'div'> {
  /** No inline padding, for a list, table or `ListDetail` that runs edge to edge; its rows' first cells keep the text on the gutter. */
  readonly bleed?: boolean;
}

export function ScreenBody({ bleed = false, className, ...props }: ScreenBodyProps) {
  return <div data-slot="screen-body" {...(bleed ? { 'data-bleed': '' } : {})} className={`${bleed ? 'py-[var(--screen-gutter,1rem)]' : 'p-[var(--screen-gutter,1rem)]'}${className ? ` ${className}` : ''}`} {...props} />;
}

'use client';

// One header per screen. A screen calls `useScreenHeader` and the shell renders it; the most recently mounted caller wins as a whole
// (a `ListDetail` inside a screen overlays « ← » and a title and keeps the screen's actions) and unmounting restores the previous one. A
// screen the shell has hidden does not count (ScreenActiveContext). Host concern: Pi has no layout.
import { createContext, createElement, useContext, useLayoutEffect, useRef, useState, useSyncExternalStore } from 'react';
import type { ComponentType, ReactNode } from 'react';
import { ArrowLeftIcon } from '../_shared/icons';
import { SidebarTrigger } from '@/components/ui/sidebar';
import { Button } from '@/components/ui/button';
import { ScreenActiveContext } from './agent-context';
import { HeaderActions } from './header-actions';
import type { ScreenHeaderAction } from './header-actions';
import { AgentTrigger } from './agent-layer';
import type { AppShellText } from './text';

interface Icon { className?: string }
export interface ScreenHeaderSpec {
  /** Default: the active nav label. */
  readonly title?: string;
  readonly subtitle?: string;
  /** Shows « ← ». */
  readonly back?: () => void;
  /** At most two are shown; the others go in « … ». */
  readonly actions?: readonly ScreenHeaderAction[];
  /** Controls rendered right after « ← » (on a phone with `compactNav="sheet"`, after the menu button), before the title: a screen that owns its row, left-aligned. */
  readonly leading?: ReactNode;
  /** The title's face: `display` (default, the theme's display font) or `sans`. */
  readonly titleFace?: 'display' | 'sans';
  /** A dense 48 px row instead of 56 px. */
  readonly dense?: boolean;
}

export type { ScreenHeaderAction } from './header-actions';

interface Entry { spec: ScreenHeaderSpec; readonly overlay: boolean }
interface Store {
  readonly entries: Entry[];
  version: number;
  readonly listeners: Set<() => void>;
}

const HeaderContext = createContext<Store | null>(null);

/** A number per icon component, so a change of icon is a change of header. */
const icons = new WeakMap<object, number>();
let iconCount = 0;
const iconId = (icon: ComponentType<Icon>): number => { let id = icons.get(icon); if (id === undefined) { iconCount += 1; id = iconCount; icons.set(icon, id); } return id; };

const touch = (store: Store) => { store.version += 1; for (const listener of [...store.listeners]) listener(); };

/** Holds the screens' headers. `AppShell` mounts one. */
export function HeaderProvider({ children }: { readonly children: ReactNode }) {
  const [store] = useState<Store>(() => ({ entries: [], version: 0, listeners: new Set() }));
  return createElement(HeaderContext.Provider, { value: store }, children);
}

/**
 * Registers the calling screen's header while it is mounted and on show. The latest spec is always read at click time. An `overlay`
 * (the shell's own `ListDetail`) is merged over the screen's header whatever the effect order: it adds « ← » and a title, and keeps the actions.
 */
export function useScreenHeader(spec: ScreenHeaderSpec, options?: { readonly overlay?: boolean }): void {
  const store = useContext(HeaderContext);
  const active = useContext(ScreenActiveContext);
  const entry = useRef<Entry>({ spec, overlay: options?.overlay === true });
  useLayoutEffect(() => { entry.current.spec = spec; });
  const key = JSON.stringify([spec.title, spec.subtitle, Boolean(spec.back), spec.titleFace, spec.dense, spec.actions?.map(action => [action.id, action.label, action.showLabel, action.href, action.target, action.rel, iconId(action.icon)])]);
  useLayoutEffect(() => {
    if (!store || !active) return;
    const mine = entry.current;
    store.entries.push(mine);
    touch(store);
    return () => { const at = store.entries.indexOf(mine); if (at >= 0) store.entries.splice(at, 1); touch(store); };
  }, [store, active]);
  // `leading` is a node with no stable key, so it is a new value on each render of the screen and touches the store each time; that only re-renders the header, which is cheap and intended.
  useLayoutEffect(() => { if (store && active) touch(store); }, [store, active, key, spec.leading]);
}

/** The header of the screen on show (the most recently mounted caller), or undefined. Re-renders when screens come and go or change their header. */
export function useTopHeader(): { readonly spec: ScreenHeaderSpec } | undefined {
  const store = useContext(HeaderContext);
  useSyncExternalStore(
    listener => { store?.listeners.add(listener); return () => { store?.listeners.delete(listener); }; },
    () => store?.version ?? 0,
    () => 0,
  );
  // A getter, so a click reads the live specs (a callback that changed without a visible change is still the current one).
  return store?.entries.length ? { get spec() { return mergedSpec(store.entries); } } : undefined;
}

/** The latest ordinary entry is the whole header; explicit overlays (the shell's `ListDetail`) are merged over it field by field. */
function mergedSpec(entries: readonly Entry[]): ScreenHeaderSpec {
  const base = entries.filter(entry => !entry.overlay).at(-1);
  const spec: Record<string, unknown> = { ...base?.spec };
  for (const entry of entries) if (entry.overlay) for (const [field, value] of Object.entries(entry.spec)) if (value !== undefined) spec[field] = value;
  return spec as ScreenHeaderSpec;
}


/**
 * The header of the screen on show: the avatar button (compact) or « ← », then the title and subtitle,
 * then the slot of the screen's own controls (`slotRef`), up to two actions, « … » and the agent trigger. `avatar` is the compact account button. `menu` (compact only) makes the leading button open the sidebar sheet and leaves the account to the sidebar's footer. The sidebar toggle of a wide screen lives in the sidebar's own header (`AppSidebar`), not here: on a phone the sheet does not exist while closed, so its opener stays in this header.
 */
export function ScreenHeader({ fallbackTitle, compact, avatar, text, slotRef, menu, screenSidebar }: { readonly menu?: boolean; readonly screenSidebar?: ReactNode; readonly fallbackTitle: string; readonly compact: boolean; readonly avatar: ReactNode; readonly text: AppShellText; readonly slotRef?: (element: HTMLElement | null) => void }) {
  const top = useTopHeader();
  const spec = top?.spec;
  const actions = spec?.actions ?? [];
  const run = (id: string) => top?.spec.actions?.find(action => action.id === id)?.onSelect();
  const back = spec?.back ? <Button variant="ghost" size="icon" data-testid="header-back" aria-label={text.goBack} title={text.goBack} onClick={() => top?.spec.back?.()}><ArrowLeftIcon data-icon="inline-start" aria-hidden="true" /></Button> : null;
  // The title starts on the screen gutter (the body's left edge) when it is the first thing in the header; a button or control before it keeps a small gap instead.
  const precedes = Boolean(spec?.leading != null || back || (compact && (menu || avatar || screenSidebar)));
  return <header data-testid="screen-header" className={`sticky top-0 z-10 flex ${spec?.dense ? 'min-h-12' : 'min-h-14'} shrink-0 items-center gap-1 bg-card px-[var(--screen-gutter,1rem)] pt-(--app-shell-safe-top)`}>
    {compact ? (back ?? (menu ? <SidebarTrigger /> : avatar)) : back}
    {compact && screenSidebar}
    {spec?.leading != null && <div data-testid="header-leading" className="flex min-w-0 shrink items-center gap-1">{spec.leading}</div>}
    <div className={`min-w-0 flex-1 pe-1 ${precedes ? 'ps-1' : ''}`}>
      <h1 data-testid="header-title" className={`m-0 truncate text-sm leading-tight font-semibold ${spec?.titleFace === 'sans' ? 'font-sans' : '[font-family:var(--font-display,var(--font-sans))]'}`}>{spec?.title ?? fallbackTitle}</h1>
      {spec?.subtitle && <p data-testid="header-subtitle" className="m-0 truncate text-xs text-muted-foreground">{spec.subtitle}</p>}
    </div>
    {/* An embedded page's own controls (`ScreenHeaderSlotContext`, for example AgentWorkspace layout="embedded"), so it needs no second row. */}
    <div ref={slotRef} data-testid="header-slot" className="flex shrink-0 items-center gap-1 empty:hidden" />
    <HeaderActions actions={actions} compact={compact} text={text} prefix="header" run={run} />
    {compact && back && !menu && avatar}
    <AgentTrigger />
  </header>;
}

'use client';

// The header actions (`ScreenHeaderAction`) and their renderer, shared by the screen header and the AgentLayer header: up to two icon or label
// buttons (or links), the rest in « … ». Imports nothing from header.tsx or agent-layer.tsx (the shell's import graph has no cycle).
import { useState } from 'react';
import type { ComponentType, MouseEvent } from 'react';
import { EllipsisIcon } from '../_shared/icons';
import { Button } from '@/components/ui/button';
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from '@/components/ui/dropdown-menu';
import { afterBack } from '../utils/back';
import { AppSheet, SHEET_ROW } from './app-sheet';
import type { AppShellText } from './text';

interface Icon { className?: string }
export interface ScreenHeaderAction {
  readonly id: string;
  /** The accessible name and the tooltip. */
  readonly label: string;
  readonly icon: ComponentType<Icon>;
  /** `'always'` also shows the label as text next to the icon (default: icon only, at every width). */
  readonly showLabel?: 'always';
  /** The action is a link (an anchor); `onSelect` still runs on click. `target` and `rel` are set only when the host passes them. */
  readonly href?: string;
  readonly target?: string;
  readonly rel?: string;
  readonly onSelect: () => void;
}

/** One action as a control: an anchor when it has `href`, else a button. `onSelect` is the caller's run (it reads the live action at click time). */
function ActionControl({ action, prefix, onSelect }: { readonly action: ScreenHeaderAction; readonly prefix: string; readonly onSelect: () => void }) {
  const content = <><action.icon data-icon="inline-start" aria-hidden="true" />{action.showLabel === 'always' && action.label}</>;
  return <Button variant="ghost" size={action.showLabel === 'always' ? 'default' : 'icon'}
    {...(action.href !== undefined ? { nativeButton: false, render: <a href={action.href} target={action.target} rel={action.rel} /> } : {})}
    data-testid={`${prefix}-action-${action.id}`} aria-label={action.label} title={action.label} onClick={onSelect}>{content}</Button>;
}

/** Up to two actions as controls; the rest go in « … » (a sheet when compact, a menu otherwise). `prefix` names the test ids. Shared with the AgentLayer header. */
export function HeaderActions({ actions, compact, text, prefix, run }: { readonly actions: readonly ScreenHeaderAction[]; readonly compact: boolean; readonly text: AppShellText; readonly prefix: string; readonly run: (id: string) => void }) {
  const shown = actions.slice(0, 2), extra = actions.slice(2);
  const [sheetOpen, setSheetOpen] = useState(false);
  // A link in the phone sheet: the sheet closes first and a same-tab navigation waits for its history entry (afterBack), so the Back
  // manager never undoes it. A new tab, or a modified click, keeps the browser's own default.
  const sheetLink = (event: MouseEvent<HTMLElement>, action: ScreenHeaderAction) => {
    setSheetOpen(false);
    if ((action.target !== undefined && action.target !== '_self') || event.metaKey || event.ctrlKey || event.shiftKey || event.button !== 0) { afterBack(() => run(action.id)); return; }
    event.preventDefault();
    const href = action.href ?? '';
    afterBack(() => { run(action.id); window.location.assign(href); });
  };
  return <>
    {shown.map(action => <ActionControl key={action.id} action={action} prefix={prefix} onSelect={() => run(action.id)} />)}
    {extra.length > 0 && (compact
      ? <>
        <Button variant="ghost" size="icon" data-testid={`${prefix}-more`} aria-label={text.actions} title={text.actions} onClick={() => setSheetOpen(true)}><EllipsisIcon data-icon="inline-start" aria-hidden="true" /></Button>
        <AppSheet open={sheetOpen} onOpenChange={setSheetOpen} title={text.actions}>
          {extra.map(action => action.href === undefined
            ? <Button key={action.id} variant="ghost" size="lg" data-testid={`${prefix}-action-${action.id}`} className={SHEET_ROW} onClick={() => { setSheetOpen(false); afterBack(() => run(action.id)); }}><action.icon data-icon="inline-start" />{action.label}</Button>
            : <Button key={action.id} variant="ghost" size="lg" nativeButton={false} render={<a href={action.href} target={action.target} rel={action.rel} />} data-testid={`${prefix}-action-${action.id}`} className={SHEET_ROW} onClick={event => sheetLink(event, action)}><action.icon data-icon="inline-start" />{action.label}</Button>)}
        </AppSheet>
      </>
      : <DropdownMenu>
        <DropdownMenuTrigger render={<Button variant="ghost" size="icon" />} data-testid={`${prefix}-more`} aria-label={text.actions} title={text.actions}><EllipsisIcon data-icon="inline-start" aria-hidden="true" /></DropdownMenuTrigger>
        <DropdownMenuContent align="end" className="app-shell w-48">
          {extra.map(action => <DropdownMenuItem key={action.id} data-testid={`${prefix}-action-${action.id}`} className="pointer-coarse:min-h-[var(--control-min,2.75rem)]" onClick={() => run(action.id)}
            render={action.href === undefined ? undefined : <a href={action.href} target={action.target} rel={action.rel} />}><action.icon className="size-4" />{action.label}</DropdownMenuItem>)}
        </DropdownMenuContent>
      </DropdownMenu>)}
  </>;
}

'use client';

// The navigation: a bottom tab bar when compact, the shadcn sidebar (icon rail plus NavUser, the sidebar-07 and sidebar-08 patterns) when
// expanded. Choosing an item only calls `route.onChange`: the app's router owns the URL, and the shell adds no history entry.
import { useEffect, useRef, useState } from 'react';
import type { ComponentType, KeyboardEvent, ReactNode } from 'react';
import { EllipsisIcon, PinIcon, SparklesIcon } from '../_shared/icons';
import { Sidebar, SidebarContent, SidebarFooter, SidebarGroup, SidebarGroupContent, SidebarHeader, SidebarMenu, SidebarMenuButton, SidebarMenuItem, SidebarSeparator, SidebarTrigger, useSidebar } from '@/components/ui/sidebar';
import { Button } from '@/components/ui/button';
import { Sheet, SheetContent, SheetDescription, SheetHeader, SheetTitle } from '@/components/ui/sheet';
import { afterBack, BACK_SETTLE_MS, useBackLayer } from '../utils/back';
import { NavUser } from './account';
import { useAgentLayer } from './agent-layer';
import type { AgentSpec } from './agent-layer';
import type { AccountSpec } from './account';
import { AppSheet, SHEET_ROW } from './app-sheet';
import { InsideNavSheet, useExclusiveSheet } from './use-exclusive-sheet';
import type { AppShellText } from './text';
import { ResizableRail } from './sidebar-resize';
import { useSidebarPin } from './sidebar-open';

export interface NavBadge {
  readonly tone: 'info' | 'success' | 'warning' | 'destructive';
  readonly label: string;
}

export interface NavItem {
  readonly id: string;
  readonly label: string;
  readonly icon: ComponentType<{ className?: string }>;
  /** A state dot on the item. Both are required, so the dot always means something: `tone` picks the colour (info, success, warning, destructive tokens), `label` is its accessible name (« Nuit à noter »). No dot, no state: leave it out. */
  readonly badge?: NavBadge;
  readonly render: () => ReactNode;
  /** The screen's own content inside the shell's sidebar (its list, say) while this item is on show: above the nav items, which move below it. `collapsed` is true on the icon rail, so the content can fold with it. */
  readonly sidebar?: (state: { readonly collapsed: boolean }) => ReactNode;
  /** The sidebar content's own name, for the phone button that opens it in tabs mode (« Library »): its label reads « <item label>: <sidebarLabel> ». Default: the shell's word for « panel ». */
  readonly sidebarLabel?: string;
  /** Where this item sits against a screen's own sidebar content: `'before-sidebar'` puts it above that content, `'after-sidebar'` (the default) below. Items marked before come first everywhere (the tab bar and the phone sheet too); each side keeps the registered order. */
  readonly placement?: 'before-sidebar' | 'after-sidebar';
}

/** The items marked `before-sidebar`, then the others, each in registered order. */
export function placeNav<T extends Pick<NavItem, 'placement'>>(items: readonly T[]): { readonly before: readonly T[]; readonly after: readonly T[] } {
  return { before: items.filter(item => item.placement === 'before-sidebar'), after: items.filter(item => item.placement !== 'before-sidebar') };
}

/** The most tabs the bar shows. */
const MAX_TABS = 4;

/** Up to four items are all tabs; more than four give three tabs and the rest behind « Plus ». */
export function splitNav<T>(items: readonly T[]): { readonly tabs: readonly T[]; readonly overflow: readonly T[] } {
  return items.length <= MAX_TABS ? { tabs: items, overflow: [] } : { tabs: items.slice(0, MAX_TABS - 1), overflow: items.slice(MAX_TABS - 1) };
}

const DOT_TONE = { info: 'bg-info', success: 'bg-success', warning: 'bg-warning', destructive: 'bg-destructive' } as const;

/** A state dot: a plain 8px span in the tone's token, named by its label. Its classes only place it. */
// A hidden comma before the dot gives screen readers a pause: the item reads « Plus, Nuit à noter », not « Plus Nuit à noter ». It is generated content, so the item's textContent stays « Plus », and it takes the dot's className so it hides with the dot (collapsed rail).
const Dot = ({ badge, className }: { readonly badge: NavBadge; readonly className?: string }) => <><span className={`sr-only before:content-[',_'] ${className ?? ''}`} /><span role="img" aria-label={badge.label} data-testid="nav-badge" className={`inline-block size-2 shrink-0 rounded-full ${DOT_TONE[badge.tone]} ${className ?? ''}`} /></>;

/** Publishes the bar's measured height as `--app-shell-tabbar` on the document root (the drawer is portaled, so the shell root is too high up to reach it). */
function useTabbarHeight(bar: { readonly current: HTMLElement | null }, shown: boolean): void {
  useEffect(() => {
    const root = document.documentElement;
    const node = bar.current;
    if (!shown || !node) { root.style.setProperty('--app-shell-tabbar', '0px'); return; }
    const measure = () => root.style.setProperty('--app-shell-tabbar', `${node.getBoundingClientRect().height}px`);
    measure();
    const observer = typeof ResizeObserver === 'function' ? new ResizeObserver(measure) : undefined;
    observer?.observe(node);
    return () => { observer?.disconnect(); root.style.removeProperty('--app-shell-tabbar'); };
  }, [bar, shown]);
}

/** Layout for a tab on the host's Button: icon over label, filling its share of the bar. */
const TAB = 'relative h-auto min-w-0 flex-1 flex-col gap-0.5';

/** The tab bar's arrow keys: Left and Right move the focus between the tabs (wrapping). */
const arrows = (event: KeyboardEvent<HTMLElement>) => {
  const buttons = [...event.currentTarget.querySelectorAll<HTMLElement>('[role=tab]')];
  const at = buttons.indexOf(document.activeElement as HTMLElement);
  const step = event.key === 'ArrowRight' ? 1 : event.key === 'ArrowLeft' ? -1 : 0;
  if (at < 0 || !step) return;
  event.preventDefault();
  buttons[(at + step + buttons.length) % buttons.length]!.focus();
};

/** The compact tab bar. With one item there is none. Exported for tests. */
export function TabBar({ items, activeId, onChange, text }: { readonly items: readonly NavItem[]; readonly activeId: string; readonly onChange: (id: string) => void; readonly text: AppShellText }) {
  const bar = useRef<HTMLElement>(null);
  const [plusOpen, setPlusOpen] = useState(false);
  const shown = items.length > 1;
  useTabbarHeight(bar, shown);
  if (!shown) return null;
  const { before, after } = placeNav(items);
  const { tabs, overflow } = splitNav([...before, ...after]);
  const inOverflow = overflow.find(item => item.id === activeId);
  /** « Plus » stands for the hidden items: it shows the dot of the first badged one other than the item on show (that one has its own tab face). */
  const hidden = overflow.find(item => item.id !== activeId && item.badge)?.badge;
  const tab = (item: NavItem) => <Button key={item.id} variant={item.id === activeId ? 'secondary' : 'ghost'} role="tab" data-testid={`tab-${item.id}`} aria-selected={item.id === activeId} tabIndex={item.id === activeId ? 0 : -1}
    onClick={() => onChange(item.id)} className={TAB}>
    <item.icon />{item.label}{item.badge && <Dot badge={item.badge} className="absolute top-1 left-1/2 ml-2" />}
  </Button>;
  // « Plus » always keeps its own icon and word (a dot belongs to the label it sits next to); the header names the screen on show.
  const Plus = overflow.length ? EllipsisIcon : undefined;
  return <nav ref={bar} role="tablist" aria-label={text.tabs} data-testid="tabbar" data-feedback-ignore="" onKeyDown={arrows}
    className="relative z-(--app-shell-z-tabs) box-border flex min-h-(--app-shell-tabbar-min) shrink-0 bg-sidebar px-2 pb-(--app-shell-safe-bottom)">
    {tabs.map(tab)}
    {Plus && <>
      <Button variant={inOverflow ? 'secondary' : 'ghost'} role="tab" data-testid="tab-plus" aria-selected={Boolean(inOverflow)} aria-haspopup="dialog" tabIndex={inOverflow ? 0 : -1} onClick={() => setPlusOpen(true)}
        className={TAB}>
        <Plus />{text.more}{hidden && <Dot badge={hidden} className="absolute top-1 left-1/2 ml-2" />}
      </Button>
      <AppSheet open={plusOpen} onOpenChange={setPlusOpen} title={text.more}>
        {overflow.map(item => <Button key={item.id} variant={item.id === activeId ? 'secondary' : 'ghost'} size="lg" data-testid={`plus-${item.id}`} aria-current={item.id === activeId} className={SHEET_ROW}
          onClick={() => { setPlusOpen(false); afterBack(() => onChange(item.id)); }}>
          <item.icon data-icon="inline-start" />{item.label}{item.badge && <Dot badge={item.badge} className="ml-auto" />}
        </Button>)}
      </AppSheet>
    </>}
  </nav>;
}

/** What keeps the sheet open, checked from the tapped element up: a field to type in, or anything under `data-keep-sheet`. */
const KEEPS = 'input, textarea, select, [contenteditable=""], [contenteditable=true], [data-keep-sheet]';
/** What a tap on a row of the sidebar content counts as « choosing a row »: it closes the sheet. A field to type in does not, and an element may opt out with `data-keep-sheet`. */
const CHOOSES = 'a, button, [role=button], [role=option], [role=menuitem], [role=treeitem], [role=row], [role=link]';

/**
 * Tabs mode on a phone: the current item's `sidebar` has no sidebar to live in, so the header carries a leading button that opens that same content in a left sheet
 * (the width of `compactNav="sheet"`). Choosing a row closes the sheet. An item without a `sidebar` renders nothing. Exported for the header.
 */
export function ScreenSidebarSheet({ item, text }: { readonly item: NavItem; readonly text: AppShellText }) {
  // `open` owns the Back entry; `shown` keeps the sheet mounted while a chosen row's click is replayed once that entry has gone.
  const [open, setOpen] = useState(false);
  const [shown, setShown] = useState(false);
  const replaying = useRef(false);
  const choosing = useRef(false);
  // The choice held behind the sheet's Back; unmounting or settling drops it.
  const pending = useRef<object | null>(null);
  useEffect(() => () => { pending.current = null; }, []);
  const close = () => { pending.current = null; choosing.current = false; setOpen(false); setShown(false); };
  useExclusiveSheet(open, close);
  useBackLayer(open, close, 'sheet');
  if (!item.sidebar) return null;
  const name = `${item.label}: ${item.sidebarLabel ?? text.panel}`;
  return <>
    <Button variant="ghost" size="icon" data-testid="screen-sidebar-button" aria-label={name} title={name} aria-haspopup="dialog" aria-expanded={open} onClick={() => { setOpen(true); setShown(true); }}><item.icon data-icon="inline-start" aria-hidden="true" /></Button>
    <Sheet open={shown} onOpenChange={next => { if (!next) close(); }}>
      <SheetContent side="left" showCloseButton={false} data-testid="screen-sidebar-sheet" className="app-shell data-[side=left]:w-[var(--sidebar-width-mobile,75%)]">
        <SheetHeader className="sr-only"><SheetTitle>{name}</SheetTitle><SheetDescription>{name}</SheetDescription></SheetHeader>
        <div data-testid="screen-sidebar-content" className="flex min-h-0 flex-1 flex-col overflow-y-auto overscroll-contain bg-sidebar pb-(--app-shell-safe-bottom) text-sidebar-foreground"
          onClickCapture={event => {
            // The choice is held back: the sheet lets go of its Back entry first, and only then does the row's own click (a router push, a link) run, so that entry's `history.back()` cannot undo it.
            const target = event.target;
            // A modified or non-primary click (new tab, new window, middle button) is not a choice: it goes through untouched and the sheet stays open.
            const { button, metaKey, ctrlKey, shiftKey, altKey } = event;
            if (replaying.current || !(target instanceof Element) || target.closest(KEEPS) || !target.closest(CHOOSES) || button !== 0 || metaKey || ctrlKey || shiftKey || altKey) return;
            event.preventDefault();
            event.stopPropagation();
            // One choice at a time: a second tap while the sheet is closing is swallowed, so a navigating row navigates once.
            if (choosing.current) return;
            choosing.current = true;
            const mine = {};
            pending.current = mine;
            setOpen(false);
            // A Back that never lands settles after a bounded wait: the choice is dropped (never run ahead of the traversal) and the sheet closes.
            setTimeout(() => { if (pending.current !== mine) return; pending.current = null; choosing.current = false; setShown(false); }, BACK_SETTLE_MS);
            afterBack(() => {
              if (pending.current !== mine) return;
              pending.current = null;
              if (target.isConnected) {
                replaying.current = true;
                try { target.dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true })); } finally { replaying.current = false; }
              }
              choosing.current = false;
              setShown(false);
            });
          }}>
          {item.sidebar({ collapsed: false })}
        </div>
      </SheetContent>
    </Sheet>
  </>;
}

/** Hover intent of the hover rail, in ms: the pointer must stay this long to reveal the pane, and be gone this long (focus too) to fold it. */
const HOVER_REVEAL_MS = 150;
const HOVER_FOLD_MS = 300;

/** The expanded sidebar: the app title, the nav items (none with one item) and the account in the footer. */
export function AppSidebar({ rail = 'icon', identity, title, items, activeId, onChange, agent, account, improve, text }: {
  readonly rail?: 'icon' | 'hover'; readonly identity?: { readonly app?: string | undefined; readonly person?: string | undefined }; readonly title: string; readonly items: readonly NavItem[]; readonly activeId: string; readonly onChange: (id: string) => void;
  readonly agent: AgentSpec | undefined; readonly account: AccountSpec | undefined; readonly improve: string | undefined; readonly text: AppShellText;
}) {
  const { setOpen, openMobile, setOpenMobile, state, isMobile } = useSidebar();
  // The hover rail's pin (D-2010): on a wide screen only. Pinned, the pane is open whatever the pointer and focus do and the page sits beside it.
  const hover = rail === 'hover' && !isMobile;
  const { pinned, set: setPinned } = useSidebarPin(hover, identity ?? {});
  const wrapper = useRef<HTMLDivElement>(null);
  // A dialog, menu or popover opened from the pane lives in a portal outside it: the pointer and focus leave the pane while it is open. Its trigger says so; the pane waits.
  const layerOpen = () => Boolean(wrapper.current?.querySelector('[aria-haspopup][aria-expanded="true"], [aria-haspopup][data-popup-open], [aria-haspopup][data-state="open"]'));
  const togglePin = () => {
    const next = !pinned;
    setPinned(next);
    // Unpinning folds unless the pointer or focus is still in the pane (then leaving does).
    const el = wrapper.current;
    setOpen(next || layerOpen() || Boolean(el && (el.matches(':hover') || el.contains(document.activeElement))));
  };
  const toggle = useRef(togglePin);
  useEffect(() => { toggle.current = togglePin; });
  useEffect(() => { if (pinned && state === 'collapsed') setOpen(true); }, [pinned, state, setOpen]);
  const settled = () => {
    const el = wrapper.current;
    try { return Boolean(el) && !el!.matches(':hover') && !(el!.contains(document.activeElement) && document.activeElement!.matches(':focus-visible')); } catch { return false; }
  };
  // Keyboard focus inside the pane (a mouse click leaves none to keep it open) and the pointer over it each keep it open: it folds when both have gone.
  const focusIn = () => { const el = wrapper.current; try { return Boolean(el && el.contains(document.activeElement) && document.activeElement!.matches(':focus-visible')); } catch { return false; } };
  const pointerIn = () => { try { return Boolean(wrapper.current?.matches(':hover')); } catch { return false; } };
  const fold = () => { if (!pinned && !layerOpen() && !pointerIn() && !focusIn()) setOpen(false); };
  // Hover intent: the pane opens once the pointer has stayed HOVER_REVEAL_MS on the rail and folds HOVER_FOLD_MS after pointer and focus left, so a pointer passing by flashes nothing. Keyboard focus opens it at once.
  const intent = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const latestFold = useRef(fold);
  useEffect(() => { latestFold.current = fold; });
  useEffect(() => () => clearTimeout(intent.current), []);
  const foldLater = () => { clearTimeout(intent.current); intent.current = setTimeout(() => latestFold.current(), HOVER_FOLD_MS); };
  // When that layer closes, the pane folds if the pointer and focus are outside (the trigger gets focus back after a pause).
  useEffect(() => {
    const el = wrapper.current;
    if (!hover || !el || pinned) return undefined;
    let timer: ReturnType<typeof setTimeout> | undefined;
    const observer = new MutationObserver(() => { clearTimeout(timer); timer = setTimeout(() => { if (!layerOpen() && settled()) setOpen(false); }, 60); });
    observer.observe(el, { subtree: true, attributes: true, attributeFilter: ['aria-expanded', 'data-popup-open'] });
    return () => { observer.disconnect(); clearTimeout(timer); };
  }, [hover, pinned, setOpen]);
  // Ctrl+B toggles the pin here, ahead of the provider's own listener (which would fold the pane under the pointer).
  useEffect(() => {
    if (!hover) return undefined;
    const onKey = (event: globalThis.KeyboardEvent) => {
      if (event.key !== 'b' || !(event.metaKey || event.ctrlKey)) return;
      // A text field or editor keeps its own Ctrl+B (bold, say).
      if (event.target instanceof Element && event.target.closest('input, textarea, select, [contenteditable]:not([contenteditable="false"])')) return;
      event.preventDefault();
      event.stopPropagation();
      toggle.current();
    };
    window.addEventListener('keydown', onKey, true);
    return () => window.removeEventListener('keydown', onKey, true);
  }, [hover]);
  // In the phone sheet, choosing a screen closes it.
  const choose = (id: string) => { setOpenMobile(false); onChange(id); };
  const own = items.find(item => item.id === activeId)?.sidebar?.({ collapsed: state === 'collapsed' && !isMobile && !pinned });
  const { before, after } = placeNav(items);
  const navGroup = (group: readonly NavItem[], className?: string, testId?: string) => group.length > 0 && <SidebarGroup className={className} data-testid={testId}><SidebarGroupContent><SidebarMenu>
    {group.map(item => <SidebarMenuItem key={item.id}>
      <SidebarMenuButton isActive={item.id === activeId} tooltip={item.label} data-testid={`nav-${item.id}`} className="pointer-coarse:min-h-[var(--control-min,2.75rem)] pointer-coarse:min-w-[var(--control-min,2.75rem)]" onClick={() => choose(item.id)}>
        <item.icon />
        <span>{item.label}</span>
        {item.badge && <Dot badge={item.badge} className="ml-auto group-data-[collapsible=icon]:hidden" />}
      </SidebarMenuButton>
    </SidebarMenuItem>)}
  </SidebarMenu></SidebarGroupContent></SidebarGroup>;
  const layer = useAgentLayer();
  // One layer at a time on a phone (D-1903): the sheet closes when the assistant or the PM opens, or when another sheet (the account's) opens.
  const covering = layer.state !== 'closed' ? layer.showing : null;
  useEffect(() => { if (covering) setOpenMobile(false); }, [covering, setOpenMobile]);
  useExclusiveSheet(isMobile && openMobile, () => setOpenMobile(false), true);
  const pressed = layer.state !== 'closed' && layer.showing === 'agent';
  const AgentIcon = agent?.icon ?? SparklesIcon;
  const agentLabel = agent?.label ?? agent?.chatProps?.labels?.title ?? text.assistant;
  // Hover-revealed and unpinned, the pane floats over the page: a shadow on its sidebar surface lifts it (pinned, it sits beside the page).
  const sidebar = <Sidebar collapsible="icon" variant="inset" data-testid="app-sidebar" data-float={hover && !pinned && state === 'expanded' ? 'true' : undefined}>
    {/* The phone sheet is portaled out of the shell root, so the `.app-shell` reset would not reach its buttons: this wrapper carries it (`contents`: no box of its own). */}
    <InsideNavSheet.Provider value={true}>
    <div className="app-shell contents">
    {/* The one toggle: title and button expanded, the button alone on the icon rail, and « close » inside the phone sheet. The hover rail has no toggle on a wide screen (it opens on hover and focus by itself) but a pin (D-2010) that keeps it open, and keeps « close » in the sheet. */}
    <SidebarHeader className="flex-row items-center justify-between gap-1 group-data-[collapsible=icon]:justify-center"><p data-testid="sidebar-title" className="m-0 min-w-0 truncate px-2 py-1 text-sm font-semibold group-data-[collapsible=icon]:hidden">{title}</p>{(rail !== 'hover' || isMobile) && <SidebarTrigger />}
      {hover && <Button type="button" variant="ghost" size="icon-sm" data-testid="sidebar-pin" aria-pressed={pinned} aria-label={text.pin} title={`${pinned ? text.unpin : text.pin} · Ctrl+B`} onClick={togglePin}
        className="group-data-[collapsible=icon]:pointer-events-none group-data-[collapsible=icon]:opacity-0 group-data-[collapsible=icon]:pointer-coarse:pointer-events-auto group-data-[collapsible=icon]:pointer-coarse:opacity-100"><PinIcon aria-hidden="true" data-pinned={pinned ? 'true' : 'false'} weight={pinned ? 'fill' : 'regular'} /></Button>}</SidebarHeader>
    <SidebarContent>
      {/* Without the screen's own content, one group in placed order; with it, the before items above it and the rest below. */}
      {items.length > 1 && own != null && navGroup(before, 'shrink-0', 'nav-before')}
      {own != null && <div data-testid="sidebar-screen" className="min-h-0 flex-1 overflow-y-auto overscroll-contain">{own}</div>}
      {items.length > 1 && (own != null ? navGroup(after, 'shrink-0') : navGroup([...before, ...after]))}
      {/* The assistant is a layer, never a destination: no route, it toggles the right panel. */}
      {agent && <>
        {items.length > 1 && <SidebarSeparator />}
        <SidebarGroup><SidebarGroupContent><SidebarMenu><SidebarMenuItem>
          <SidebarMenuButton isActive={pressed} aria-pressed={pressed} tooltip={agentLabel} data-testid="nav-agent" className="pointer-coarse:min-h-[var(--control-min,2.75rem)] pointer-coarse:min-w-[var(--control-min,2.75rem)]"
            onClick={() => { setOpenMobile(false); if (pressed) layer.close(); else layer.open('agent', 'half'); }}>
            <AgentIcon /><span>{agentLabel}</span>
          </SidebarMenuButton>
        </SidebarMenuItem></SidebarMenu></SidebarGroupContent></SidebarGroup>
      </>}
    </SidebarContent>
    <SidebarFooter><NavUser account={account} improve={improve} text={text} /></SidebarFooter>
    <ResizableRail />
    </div>
    </InsideNavSheet.Provider>
  </Sidebar>;
  if (rail !== 'hover') return sidebar;
  // Reserve the native inset icon gap even while the fixed sidebar reveals its labels over the page.
  return <div ref={wrapper} data-rail="hover" data-pinned={pinned} className={pinned ? 'relative z-20 shrink-0' : 'relative z-20 w-[calc(var(--sidebar-w-icon)+(--spacing(4)))] shrink-0'}
    onPointerEnter={event => { if (event.pointerType === 'mouse' || event.pointerType === 'pen') { clearTimeout(intent.current); intent.current = setTimeout(() => setOpen(true), HOVER_REVEAL_MS); } }}
    onPointerLeave={foldLater}
    onFocusCapture={event => { if (event.target.matches(':focus-visible')) { clearTimeout(intent.current); setOpen(true); } }}
    onBlurCapture={event => { if (!event.currentTarget.contains(event.relatedTarget)) foldLater(); }}
    onKeyDownCapture={event => { if (!pinned && event.key === 'Escape' && event.target instanceof Node && event.currentTarget.contains(event.target)) { event.preventDefault(); event.stopPropagation(); clearTimeout(intent.current); setOpen(false); } }}>
    {sidebar}
  </div>;
}

'use client';

// The account choices: the compact sheet's content (`AccountChoices`) and the expanded sidebar's footer (`NavUser`, the sidebar-07 pattern).
// Both list « Améliorer l'app » (when the app has an `improve` agent, opened in the AgentLayer), the app's own `menu`, then sign out.
import { useId } from 'react';
import type { CSSProperties } from 'react';
import { ChevronsUpDownIcon, LogOutIcon, MessageSquarePlusIcon, MoonIcon } from '../_shared/icons';
import { Avatar, AvatarFallback } from '@/components/ui/avatar';
import { Button } from '@/components/ui/button';
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuSeparator, DropdownMenuTrigger } from '@/components/ui/dropdown-menu';
import { SidebarMenu, SidebarMenuButton, SidebarMenuItem } from '@/components/ui/sidebar';
import { useAgentLayer } from './agent-layer';
import { afterBack } from '../utils/back';
import { Switch } from '@/components/ui/switch';
import { DropdownMenuCheckboxItem } from '@/components/ui/dropdown-menu';
import { SHEET_ROW } from './app-sheet';
import type { AppShellText } from './text';

export interface AccountSpec {
  readonly name: string;
  readonly email?: string;
  readonly signOut?: () => void;
  readonly menu: readonly { readonly label: string; readonly onSelect: () => void }[];
  /** The app's resolved theme: one « Mode sombre » switch in the account menu. The host resolves `system` (its preference) to `light` or `dark` before it gets here. Absent: no row. */
  readonly theme?: { readonly value: 'light' | 'dark'; readonly onChange: (value: 'light' | 'dark') => void };
}

/** « Améliorer l'app »'s row: 52px as a height, not a minimum, so the shell's 44px touch-target `min-height` (more specific) cannot shrink it. Its radius: the theme's large radius plus one step (12px on a 8px theme). */
const IMPROVE_ROW = { '--radius': 'var(--app-shell-row-radius)' } as CSSProperties;

/** The switch's state: on is dark. */
const darkOn = (theme: NonNullable<AccountSpec['theme']>) => theme.value === 'dark';

function ThemeSwitch({ theme, text }: { readonly theme: NonNullable<AccountSpec['theme']>; readonly text: AppShellText }) {
  const id = useId();
  return <div className="flex items-center gap-3">
    <label htmlFor={id} className="flex min-h-11 items-center gap-3"><MoonIcon aria-hidden="true" />{text.darkMode}</label>
    <Switch id={id} data-testid="account-theme" aria-label={text.darkMode} checked={darkOn(theme)} className="ml-auto" onCheckedChange={on => theme.onChange(on ? 'dark' : 'light')} />
  </div>;
}

/** « Jean Dupont » gives « JD »; one word gives its first letter. */
export function initials(name: string): string {
  const letters = name.trim().split(/\s+/).filter(Boolean).slice(0, 2).map(word => [...word][0]!.toUpperCase());
  return letters.join('') || '?';
}

export function AccountAvatar({ account, size }: { readonly account: AccountSpec | undefined; readonly size?: 'default' | 'lg' }) {
  return <Avatar size={size === 'lg' ? 'lg' : 'default'}><AvatarFallback>{initials(account?.name ?? '')}</AvatarFallback></Avatar>;
}

/** The compact account sheet's content. Every choice closes the sheet first (`done`). */
export function AccountChoices({ account, improve, text, done }: { readonly account: AccountSpec | undefined; readonly improve: string | undefined; readonly text: AppShellText; readonly done: () => void }) {
  const layer = useAgentLayer();
  const choose = (action: () => void) => () => { done(); afterBack(action); };
  return <div data-testid="account-menu" className="flex flex-col" style={{ '--app-shell-row-radius': 'calc(var(--radius) + 4px)' } as CSSProperties}>
    {account && <div className="flex items-center gap-3 px-4 py-3">
      <AccountAvatar account={account} size="lg" />
      <div className="min-w-0"><p className="m-0 truncate font-medium">{account.name}</p>{account.email && <p className="m-0 truncate text-xs text-muted-foreground">{account.email}</p>}</div>
    </div>}
    {/* C1: the first item, 52px on the muted fill, the speech bubble with a plus (icon 20), 15/650. */}
    {improve && <Button variant="secondary" size="lg" data-testid="account-improve" className={`${SHEET_ROW} h-13`} style={IMPROVE_ROW} onClick={choose(() => layer.open('improve'))}><MessageSquarePlusIcon data-icon="inline-start" className="size-5" aria-hidden="true" /><span className="text-base font-pm-title">{improve}</span></Button>}
    {account?.menu.map(entry => <Button key={entry.label} variant="ghost" size="lg" className={SHEET_ROW} onClick={choose(entry.onSelect)}>{entry.label}</Button>)}
    {account?.theme && <ThemeSwitch theme={account.theme} text={text} />}
    {account?.signOut && <Button variant="ghost" size="lg" data-testid="account-sign-out" className={SHEET_ROW} onClick={choose(account.signOut)}><LogOutIcon data-icon="inline-start" aria-hidden="true" />{text.signOut}</Button>}
  </div>;
}

/** The expanded sidebar footer: avatar, name and a dropdown with the same entries as the compact sheet. */
export function NavUser({ account, improve, text }: { readonly account: AccountSpec | undefined; readonly improve: string | undefined; readonly text: AppShellText }) {
  const layer = useAgentLayer();
  if (!account && !improve) return null;
  return <SidebarMenu><SidebarMenuItem>
    <DropdownMenu>
      <DropdownMenuTrigger render={<SidebarMenuButton size="lg" data-testid="nav-user" className="pointer-coarse:min-h-[var(--control-min,2.75rem)] pointer-coarse:min-w-[var(--control-min,2.75rem)]" />}>
        <AccountAvatar account={account} />
        <div className="grid min-w-0 flex-1 text-left text-xs leading-tight">
          <span className="truncate font-medium">{account?.name ?? text.account}</span>
          {account?.email && <span className="truncate text-xs text-muted-foreground">{account.email}</span>}
        </div>
        <ChevronsUpDownIcon className="ml-auto size-4" aria-hidden="true" />
      </DropdownMenuTrigger>
      <DropdownMenuContent side="right" align="end" sideOffset={4} className="app-shell w-56 min-w-56">
        {improve && <DropdownMenuItem className="pointer-coarse:min-h-[var(--control-min,2.75rem)]" data-testid="account-improve" onClick={() => layer.open('improve')}><MessageSquarePlusIcon className="size-4" aria-hidden="true" />{improve}</DropdownMenuItem>}
        {account?.menu.map(entry => <DropdownMenuItem key={entry.label} className="pointer-coarse:min-h-[var(--control-min,2.75rem)]" onClick={entry.onSelect}>{entry.label}</DropdownMenuItem>)}
        {account?.theme && <DropdownMenuCheckboxItem checked={darkOn(account.theme)} closeOnClick data-testid="account-theme" className="pointer-coarse:min-h-[var(--control-min,2.75rem)]" onCheckedChange={on => account.theme?.onChange(on ? 'dark' : 'light')}><MoonIcon aria-hidden="true" />{text.darkMode}</DropdownMenuCheckboxItem>}
        {account?.signOut && <><DropdownMenuSeparator /><DropdownMenuItem className="pointer-coarse:min-h-[var(--control-min,2.75rem)]" data-testid="account-sign-out" onClick={account.signOut}><LogOutIcon className="size-4" aria-hidden="true" />{text.signOut}</DropdownMenuItem></>}
      </DropdownMenuContent>
    </DropdownMenu>
  </SidebarMenuItem></SidebarMenu>;
}

'use client';

// The one sheet of the shell (account, « Plus », « … », app flows): the host's shadcn `drawer`, a modal bottom sheet. Only one is open at a time
// (opening one closes any other) and Back closes it (the Back manager's `sheet` layer). The agent layer is not an AppSheet.
import type { ReactNode } from 'react';
import { Drawer, DrawerContent, DrawerHeader, DrawerTitle } from '@/components/ui/drawer';
import { useBackLayer } from '../utils/back';
import { useExclusiveSheet } from './use-exclusive-sheet';

/** A modal bottom sheet with a title. The scrim, Escape, a swipe down and Back close it. */
export function AppSheet({ open, onOpenChange, title, children }: { readonly open: boolean; readonly onOpenChange: (open: boolean) => void; readonly title: string; readonly children: ReactNode }) {
  const close = () => onOpenChange(false);
  useExclusiveSheet(open, close);
  useBackLayer(open, close, 'sheet');
  return <Drawer open={open} onOpenChange={next => { if (!next) close(); }} showSwipeHandle swipeDirection="down">
    <DrawerContent data-testid="app-sheet" className="app-shell max-h-(--app-shell-sheet-max)">
      <DrawerHeader><DrawerTitle>{title}</DrawerTitle></DrawerHeader>
      <div className="flex min-h-0 flex-1 flex-col overflow-y-auto overscroll-contain px-2 pt-2 pb-(--app-shell-safe-bottom)">{children}</div>
    </DrawerContent>
  </Drawer>;
}

/** Layout for a full-width sheet row on the host's ghost `Button`: at least 48px tall (44px is the touch minimum). */
export const SHEET_ROW = 'min-h-12 w-full justify-start gap-3';

'use client';

import { createContext, useContext, useEffect, useLayoutEffect, useRef } from 'react';

interface Open { readonly close: () => void; /** The phone nav sheet itself. */ readonly nav: boolean }
const opened = new Set<Open>();

/** True inside the phone nav sheet's content: a sheet opened from there is nested (it stacks on the nav sheet, whose subtree it lives in) and does not close it. */
export const InsideNavSheet = createContext(false);

/** While `open`, this sheet is the only one: every other open sheet is asked to close when it opens, except the nav sheet a nested sheet lives in. `nav` marks the phone nav sheet's own registration. */
export function useExclusiveSheet(open: boolean, close: () => void, nav = false): void {
  const latest = useRef(close);
  const nested = useContext(InsideNavSheet);
  useLayoutEffect(() => { latest.current = close; });
  useEffect(() => {
    if (!open) return;
    const mine: Open = { close: () => latest.current(), nav };
    for (const other of [...opened]) if (!(nested && other.nav)) other.close();
    opened.add(mine);
    return () => { opened.delete(mine); };
  }, [open, nested, nav]);
}

'use client';

// The shell's panel place: a second agent or tool beside the app, opened from the account menu. The shell knows only this shape, so an app
// plugs in what it wants (the product manager is `pmPanel` from the Factory's `platform-ui/pm-panel`) and an app without one installs nothing more.
import type { ComponentType, ReactNode } from 'react';

export interface ShellPanelProviderProps {
  /** `ShellPanel.config`, as the panel wrote it. */
  readonly config: unknown;
  readonly open: boolean;
  readonly close: () => void;
  readonly appName?: string | undefined;
  readonly locale?: string | undefined;
  /** The panel took the whole screen, or gave it back; `collapse` is what Back runs. */
  readonly onFull?: ((full: boolean, collapse: () => void) => void) | undefined;
  readonly children: ReactNode;
}

export interface ShellPanelLayoutProps {
  readonly children: ReactNode;
  /** The phone tab bar. The layout hides it while the panel covers the page. */
  readonly navigation?: ReactNode;
  /** The label of the screen on show. */
  readonly screen?: string;
}

export interface ShellPanelPageProps {
  readonly config: unknown;
  readonly appName: string;
  readonly locale?: string | undefined;
}

/** Keep `Provider`, `Layout` and `page.Page` the same across renders: a new component remounts the app. */
export interface ShellPanel {
  /** Passed back to `Provider` and `page.Page`. */
  readonly config: unknown;
  /** Wraps the whole shell, so the panel's state outlives its closing. */
  readonly Provider: ComponentType<ShellPanelProviderProps>;
  /** Wraps the screen and draws the panel beside it. */
  readonly Layout: ComponentType<ShellPanelLayoutProps>;
  /** The account menu's row and the layer's title. Default: the shell's « Améliorer l'app ». */
  readonly label?: string;
  /** `false`: no account menu row for the panel, which still mounts (a host that already shows the panel, around a framed app). Default: the row. */
  readonly menu?: false;
  /** The panel's language, for the shell's own words when the app has no agent to say it. */
  readonly locale?: string | undefined;
  /** Changes when the panel's conversation changes; a launch link's focus waits on it. */
  readonly identity?: unknown;
  /** The address that shows only the panel, without the shell. */
  readonly page?: { readonly matches: () => boolean; readonly Page: ComponentType<ShellPanelPageProps> };
}

/** The screen when the app has no panel. */
export function NoPanelLayout({ children, navigation }: ShellPanelLayoutProps) {
  return <div className="relative flex min-h-0 min-w-0 flex-1 flex-col overflow-hidden">
    <div className="flex min-h-0 min-w-0 flex-1 flex-col overflow-hidden">{children}</div>
    <div className="shrink-0 md:hidden">{navigation}</div>
  </div>;
}

'use client';

// The resizable left pane (D-1898), owned by the kit and independent of the host's shadcn sidebar: the host's SidebarProvider takes no kit-only
// prop. The width is the `--sidebar-width` custom property on the provider's wrapper (the theme token the sidebar already reads), so the host's
// own sidebar needs no change; the rail becomes the drag handle (role separator, arrow keys, double-click reset). Fine pointers only: on touch
// the rail stays the host's toggle and the phone sheet keeps `--sidebar-width-mobile`.
// The width the person chose is kept in rem in localStorage under the kit's own key, which names the app and, when it is known, the person: another
// person on the same browser, or another app on the same origin, starts from the theme's width. Every storage access is guarded: a blocked or
// throwing store only means the width is not remembered.
// An app that renders SidebarProvider itself uses ResizableSidebarProvider and ResizableRail in its place: the same behaviour, no AppShell.
import { createContext, useCallback, useContext, useEffect, useLayoutEffect, useMemo, useRef, useState, type ComponentProps, type CSSProperties } from 'react';
import { SidebarProvider, SidebarRail, useSidebar } from '@/components/ui/sidebar';
import { cn } from '../utils/utils';

export const SIDEBAR_WIDTH_KEY = 'boring-ui:sidebar-width';
/** The storage key of one sidebar setting for an app and a person: `boring-ui:sidebar-<setting>:<app>:<person>`; with no person, `:<app>`; with neither, the bare prefix. The person is never dropped: with no app the app part is empty. The width (D-1898) and the open state (D-1909) share this one scheme; the open state of the `screen` layout is its own setting, `open-screen` (D-1919). */
export function sidebarKey(setting: 'width' | 'open' | 'open-screen' | 'pin' | 'agent-mode' | 'agent-mode-screen', app?: string, person?: string): string {
  const part = (value: string | undefined) => `:${encodeURIComponent(value ?? '')}`;
  return `boring-ui:sidebar-${setting}${app || person ? part(app) : ''}${person ? part(person) : ''}`;
}
/** The stored width's key: `boring-ui:sidebar-width:<app>:<person>`. */
export function sidebarWidthKey(app?: string, person?: string): string {
  return sidebarKey('width', app, person);
}
/** The least width (D-1969): 14rem = 224px, so item names are not truncated. The one place; a stored narrower width is clamped to it on read. */
const MIN_REM = 14;
const MAX_REM = 28;
const STEP_REM = 1;

export type SidebarResizable = boolean | { readonly min?: number; readonly max?: number };

export interface SidebarResize {
  /** The storage key of this app and person: a drag started under another key is cancelled. */
  readonly storageKey: string;
  readonly minRem: number;
  readonly maxRem: number;
  /** The wrapper's style: the chosen `--sidebar-width`, or none (the theme's width). */
  readonly style: CSSProperties | undefined;
  readonly widthRem: number | null;
  readonly set: (rem: number, commit: boolean) => void;
  readonly reset: () => void;
}

function readStored(key: string, min: number, max: number): number | null {
  try {
    const stored = window.localStorage.getItem(key) ?? '';
    // The whole value must be a number: `20garbage` is not 20rem.
    return /^\d+(\.\d+)?$/.test(stored) ? Math.min(max, Math.max(min, Number(stored))) : null;
  } catch {
    return null;
  }
}

function writeStored(key: string, rem: number | null) {
  try {
    if (rem === null) window.localStorage.removeItem(key);
    else window.localStorage.setItem(key, String(rem));
  } catch {
    // storage unavailable: the width lasts for this visit only
  }
}

const useIsoLayoutEffect = typeof window === 'undefined' ? useEffect : useLayoutEffect;
const rootRem = () => Number.parseFloat(getComputedStyle(document.documentElement).fontSize) || 16;
const roundRem = (rem: number) => Math.round(rem * 10) / 10;

/** The resize state of the shell. `undefined` while `resizable` is off or the pointer is not fine. Call it where the SidebarProvider is rendered. */
export function useSidebarResize(resizable: SidebarResizable | undefined, identity: { readonly app?: string | undefined; readonly person?: string | undefined } = {}): SidebarResize | undefined {
  const storageKey = sidebarWidthKey(identity.app, identity.person);
  const bounds = typeof resizable === 'object' ? resizable : {};
  const minRem = bounds.min ?? MIN_REM;
  const maxRem = Math.max(minRem, bounds.max ?? MAX_REM);
  const [fine, setFine] = useState(false);
  const [widthRem, setWidthRem] = useState<number | null>(null);
  const on = Boolean(resizable);
  useIsoLayoutEffect(() => {
    if (!on) return;
    const query = window.matchMedia('(pointer: fine)');
    const sync = () => setFine(query.matches);
    sync();
    query.addEventListener('change', sync);
    return () => query.removeEventListener('change', sync);
  }, [on]);
  const active = on && fine;
  useIsoLayoutEffect(() => { if (active) setWidthRem(readStored(storageKey, minRem, maxRem)); }, [active, storageKey, minRem, maxRem]);
  const set = useCallback((rem: number, commit: boolean) => {
    const next = Math.min(maxRem, Math.max(minRem, rem));
    setWidthRem(next);
    if (commit) writeStored(storageKey, next);
  }, [storageKey, minRem, maxRem]);
  const reset = useCallback(() => { setWidthRem(null); writeStored(storageKey, null); }, [storageKey]);
  const style = useMemo<CSSProperties | undefined>(() => (active && widthRem !== null ? ({ '--sidebar-width': `${widthRem}rem` } as CSSProperties) : undefined), [active, widthRem]);
  return useMemo(() => (active ? { storageKey, minRem, maxRem, style, widthRem, set, reset } : undefined), [active, storageKey, minRem, maxRem, style, widthRem, set, reset]);
}

// The rail's look is the host sidebar's own (same classes), so the handle sits exactly where the toggle did.
const RAIL = cn(
  'absolute inset-y-0 z-20 hidden w-4 transition-all ease-linear group-data-[side=left]:-right-4 group-data-[side=right]:left-0 after:absolute after:inset-y-0 after:start-1/2 after:w-[2px] hover:after:bg-sidebar-border sm:flex ltr:-translate-x-1/2 rtl:-translate-x-1/2',
  'group-data-[collapsible=offcanvas]:translate-x-0 group-data-[collapsible=offcanvas]:after:left-full hover:group-data-[collapsible=offcanvas]:bg-sidebar',
  '[[data-side=left][data-collapsible=offcanvas]_&]:-right-2 [[data-side=right][data-collapsible=offcanvas]_&]:-left-2',
  'cursor-col-resize touch-none',
);

const ResizeContext = createContext<SidebarResize | undefined>(undefined);

export type ResizableSidebarProviderProps = ComponentProps<typeof SidebarProvider> & {
  /** `true` or `{ min, max }` in rem (12 and 28). Off: this is the host's SidebarProvider. */
  readonly resizable?: SidebarResizable | undefined;
  /** The app's name and the signed-in person's id or email: the stored width is theirs. With no person it is the app's. */
  readonly app?: string | undefined;
  readonly person?: string | undefined;
};

/** The host's SidebarProvider with a resizable left pane, for an app that renders the provider itself. Put `ResizableRail` in the Sidebar where `SidebarRail` was. */
export function ResizableSidebarProvider({ resizable, app, person, style, ...props }: ResizableSidebarProviderProps) {
  const resize = useSidebarResize(resizable, { app, person });
  return <ResizeContext value={resize}><SidebarProvider style={resize?.style ? { ...style, ...resize.style } : style} {...props} /></ResizeContext>;
}

/** The rail of the sidebar: the host's toggle, or, under a resizable provider (fine pointer, expanded, wide), the drag handle. */
export function ResizableRail() {
  const resize = useContext(ResizeContext);
  const { isMobile, state } = useSidebar();
  if (!resize || isMobile || state !== 'expanded') return <SidebarRail />;
  return <ResizeHandle resize={resize} />;
}

function ResizeHandle({ resize }: { readonly resize: SidebarResize }) {
  const drag = useRef<{ x: number; rem: number; sign: number; moved: boolean } | null>(null);
  const [measured, setMeasured] = useState<number | null>(null);
  const ref = useRef<HTMLDivElement>(null);
  const gap = () => ref.current?.closest('[data-slot=sidebar-wrapper]')?.querySelector<HTMLElement>('[data-slot=sidebar-gap]') ?? null;
  // The width in rem: the chosen one, else what the theme gives (the gap's own width).
  const current = () => resize.widthRem ?? (gap()?.getBoundingClientRect().width ?? 0) / rootRem();
  // The theme's width, until one is chosen: read from the gap in an observer callback (a subscription), not in an effect body.
  useEffect(() => {
    const element = ref.current?.closest('[data-slot=sidebar-wrapper]')?.querySelector<HTMLElement>('[data-slot=sidebar-gap]');
    if (!element || typeof ResizeObserver === 'undefined') return undefined;
    const observer = new ResizeObserver(() => setMeasured(element.getBoundingClientRect().width / rootRem()));
    observer.observe(element);
    return () => observer.disconnect();
  }, []);
  const direction = () => (ref.current?.closest('[data-side]')?.getAttribute('data-side') === 'right' ? -1 : 1);
  const to = (start: { x: number; rem: number; sign: number }, clientX: number) => start.rem + ((clientX - start.x) * start.sign) / rootRem();
  // The sidebar animates its width; following the pointer must not lag behind it. The inline transitions are put back as they were when the drag
  // ends however it ends: release, cancel, a lost pointer capture, or the handle leaving (Ctrl+B mid-drag collapses the sidebar and unmounts it).
  const held = useRef<Array<readonly [HTMLElement, string]>>([]);
  const settle = useCallback(() => {
    for (const [element, transition] of held.current) element.style.transition = transition;
    held.current = [];
  }, []);
  const follow = (on: boolean) => {
    if (!on) { settle(); return; }
    settle();
    const wrapper = ref.current?.closest('[data-slot=sidebar-wrapper]');
    for (const element of wrapper?.querySelectorAll<HTMLElement>('[data-slot=sidebar-gap], [data-slot=sidebar-container]') ?? []) {
      held.current.push([element, element.style.transition]);
      element.style.transition = 'none';
    }
  };
  // The drag belongs to the key it started under: if the person (or app) changes mid-drag, it is cancelled, so the width is never written under the
  // other key. The hook has already read that key's own width. The same cleanup puts the transitions back when the handle leaves.
  useEffect(() => () => { drag.current = null; settle(); }, [resize.storageKey, settle]);
  return <div
    ref={ref}
    data-sidebar="rail"
    data-slot="sidebar-rail"
    role="separator"
    aria-orientation="vertical"
    aria-label="Resize sidebar"
    aria-valuemin={resize.minRem}
    aria-valuemax={resize.maxRem}
    aria-valuenow={roundRem(resize.widthRem ?? measured ?? 0) || undefined}
    tabIndex={0}
    title="Resize sidebar (double-click to reset)"
    className={RAIL}
    onPointerDown={event => {
      if (event.button !== 0) return;
      event.currentTarget.setPointerCapture(event.pointerId);
      drag.current = { x: event.clientX, rem: current(), sign: direction(), moved: false };
      follow(true);
    }}
    onPointerMove={event => {
      const start = drag.current;
      if (!start) return;
      start.moved = true;
      resize.set(to(start, event.clientX), false);
    }}
    onPointerUp={event => {
      const start = drag.current;
      drag.current = null;
      follow(false);
      if (start?.moved) resize.set(to(start, event.clientX), true);
    }}
    onPointerCancel={() => { drag.current = null; follow(false); }}
    onLostPointerCapture={() => { drag.current = null; follow(false); }}
    onDoubleClick={resize.reset}
    onKeyDown={event => {
      const grow = direction() === 1 ? 'ArrowRight' : 'ArrowLeft';
      const shrink = grow === 'ArrowRight' ? 'ArrowLeft' : 'ArrowRight';
      let rem: number | null = null;
      if (event.key === grow) rem = current() + STEP_REM;
      else if (event.key === shrink) rem = current() - STEP_REM;
      else if (event.key === 'Home') rem = resize.minRem;
      else if (event.key === 'End') rem = resize.maxRem;
      if (rem === null) return;
      event.preventDefault();
      resize.set(rem, true);
    }}
  />;
}

'use client';

// Whether the wide-screen left pane is open (D-1909), owned by the kit around the host's SidebarProvider (controlled `open` / `onOpenChange`; the stock
// sidebar is untouched). The person's last choice (Ctrl+B, the trigger, the rail) is kept in localStorage under the same key family and identity as the
// width (`sidebarKey('open', app, person)`, and `'open-screen'` for the `screen` layout, so a fold in one layout is not read by the other (D-1919): "1" or "0", anything else ignored). With no stored choice the first visit decides once, at mount (and when the
// person changes): at 1280px and wider the pane opens when the screen on show has a `sidebar` content, else it is the icon rail; narrower, today's default.
// Navigating between screens never re-decides. Every storage access is guarded; a blocked store only means the choice is not remembered. Written on change
// only, under the key of the person who made it.
import { useCallback, useEffect, useLayoutEffect, useRef, useState } from 'react';
import { sidebarKey } from './sidebar-resize';

/** The width from which a first visit opens the pane for a screen that has a sidebar. */
export const SIDEBAR_FIRST_VISIT_MIN = 1280;

const useIsoLayoutEffect = typeof window === 'undefined' ? useEffect : useLayoutEffect;

function readOpen(key: string): boolean | null {
  try {
    const stored = window.localStorage.getItem(key);
    return stored === '1' ? true : stored === '0' ? false : null;
  } catch {
    return null;
  }
}

function writeOpen(key: string, open: boolean) {
  try {
    window.localStorage.setItem(key, open ? '1' : '0');
  } catch {
    // storage unavailable: the choice lasts for this visit only
  }
}

function wide(): boolean {
  try {
    return window.matchMedia(`(min-width: ${SIDEBAR_FIRST_VISIT_MIN}px)`).matches;
  } catch {
    return false;
  }
}

/**
 * The controlled `open` and `onOpenChange` of the SidebarProvider. `fallback` is today's default (the pane is open on the `screen` layout); `hasSidebar` is whether
 * the screen on show has a `sidebar` content. Off (`enabled` false): `undefined`, and the provider keeps its own `defaultOpen`.
 */
export function useSidebarOpen(enabled: boolean, identity: { readonly app?: string | undefined; readonly person?: string | undefined }, screenLayout: boolean, fallback: boolean, hasSidebar: boolean) {
  const key = sidebarKey(screenLayout ? 'open-screen' : 'open', identity.app, identity.person);
  const [open, setOpen] = useState(fallback);
  const latest = useRef({ fallback, hasSidebar });
  // The screen on show and today's default as of the last commit: read when the person (key) changes, not a dependency of it.
  useIsoLayoutEffect(() => { latest.current = { fallback, hasSidebar }; }, [fallback, hasSidebar]);
  // Mount, or another person: that person's stored choice, else the first-visit default. Not on a change of screen.
  useIsoLayoutEffect(() => {
    if (!enabled) return;
    const choice = readOpen(key);
    const now = latest.current;
    setOpen(choice ?? (wide() ? now.fallback || now.hasSidebar : now.fallback));
  }, [enabled, key]);
  const onOpenChange = useCallback((next: boolean) => {
    setOpen(next);
    writeOpen(key, next);
  }, [key]);
  return enabled ? { open, onOpenChange } : undefined;
}

/**
 * The pin of the hover rail (D-2010): kept open whatever the pointer and focus do. Stored under `sidebarKey('pin', app, person)` ("1" or "0", anything else ignored),
 * read at mount and when the person changes, written on a change only. `enabled` is false off the hover rail: never pinned, nothing read or written.
 */
export function useSidebarPin(enabled: boolean, identity: { readonly app?: string | undefined; readonly person?: string | undefined }) {
  const key = sidebarKey('pin', identity.app, identity.person);
  const [pinned, setPinned] = useState(false);
  useIsoLayoutEffect(() => { setPinned(enabled && readOpen(key) === true); }, [enabled, key]);
  const set = useCallback((next: boolean) => {
    setPinned(next);
    writeOpen(key, next);
  }, [key]);
  return { pinned: enabled && pinned, set };
}

